// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address to, uint256 depositAmount) public {
        vm.assume(to != address(0));
        vm.assume(depositAmount > 0);
        address creator = address(0x1000);
        vm.deal(creator, depositAmount);
        vm.prank(creator);
        c = new Wallet();
        vm.deal(creator, depositAmount);
        vm.prank(creator);
        c.deposit{value: depositAmount}();
        uint256 preBalance = address(c).balance;
        uint256 preToBalance = to.balance;
        vm.prank(creator);
        try c.migrateTo(to) { } catch { }
        uint256 postBalance = address(c).balance;
        uint256 postToBalance = to.balance;
        assertTrue(postBalance == 0 && (postToBalance - preToBalance) == preBalance - postBalance);
    }
}
